sections.content:
.btn {
  background: #6366f1;
  transform: translateY(0);
  box-shadow: 0 4px 6px rgba(0,0,0,0.1);

  /* property | duration | easing | delay */
  transition: background 0.2s ease,
              transform 0.2s ease,
              box-shadow 0.2s ease;
  /* Or: transition: all 0.2s ease; (avoid in production — too broad) */
}

.btn:hover {
  background: #4f46e5;
  transform: translateY(-2px);
  box-shadow: 0 8px 25px rgba(99,102,241,0.4);
}

/* Timing functions */
.ease   { transition-timing-function: ease; }       /* default */
.linear { transition-timing-function: linear; }
.bounce { transition-timing-function: cubic-bezier(0.34, 1.56, 0.64, 1); }

@keyframes slide-in {
  from {
    opacity: 0;
    transform: translateY(24px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes pulse {
  0%, 100% { transform: scale(1); opacity: 1; }
  50%       { transform: scale(1.05); opacity: 0.8; }
}

@keyframes spin {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}

.card {
  animation: slide-in 0.5s cubic-bezier(0.16, 1, 0.3, 1) both;
  /* name | duration | easing | fill-mode */
}

.badge {
  animation: pulse 2s ease-in-out infinite;
}

.spinner {
  animation: spin 1s linear infinite;
}

/* Stagger with animation-delay */
.card:nth-child(1) { animation-delay: 0ms; }
.card:nth-child(2) { animation-delay: 100ms; }
.card:nth-child(3) { animation-delay: 200ms; }

/* 2D transforms */
.move   { transform: translate(50px, 20px); }  /* right, down */
.moveX  { transform: translateX(50px); }
.moveY  { transform: translateY(-20px); }      /* up */
.grow   { transform: scale(1.5); }             /* 150% size */
.shrink { transform: scale(0.8); }
.spin   { transform: rotate(45deg); }
.tilt   { transform: skew(10deg, 0deg); }

/* Multiple transforms — right to left order matters! */
.combined {
  transform: translateY(-4px) scale(1.05) rotate(2deg);
}

/* 3D transforms */
.flip-card {
  transform: perspective(1000px) rotateY(180deg);
  transform-style: preserve-3d;
  backface-visibility: hidden;
}

/* transform-origin: change the pivot point */
.corner-rotate {
  transform-origin: top left;
  transform: rotate(45deg);
}

/* Mobile-first base styles */
.nav { display: none; }
.hero h1 { font-size: 1.75rem; }
.card-grid { grid-template-columns: 1fr; }

/* Tablet: 768px+ */
@media (min-width: 768px) {
  .nav { display: flex; }
  .hero h1 { font-size: 2.5rem; }
  .card-grid { grid-template-columns: repeat(2, 1fr); }
}

/* Desktop: 1200px+ */
@media (min-width: 1200px) {
  .hero h1 { font-size: 3.5rem; }
  .card-grid { grid-template-columns: repeat(3, 1fr); }
}

/* Dark mode preference */
@media (prefers-color-scheme: dark) {
  :root { --bg: #0a0a0a; --text: #f5f5f5; }
}

/* Reduced motion preference */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

/* Enable container queries on the parent */
.card-wrapper {
  container-type: inline-size;
  container-name: card;
}

/* Style based on the container width, not viewport */
@container card (min-width: 600px) {
  .card {
    display: grid;
    grid-template-columns: 200px 1fr;
  }
}

/* :has() — the 'parent selector' CSS never had */
/* Style a form that contains an invalid input */
form:has(input:invalid) .submit-btn {
  opacity: 0.5;
  pointer-events: none;
}

/* Style .card if it contains an img */
.card:has(img) .card__content {
  padding-top: 0;
}

/* aspect-ratio — prevent layout shift */
.video-wrapper {
  aspect-ratio: 16 / 9;
  width: 100%;
}
